def _trendauditbatch_diff_stats(stats_report):
    """从单项 stats 报告聚合 ba/f1：regressions 求和、worst_delta 取最小。

    stats_report 为 _trendstats_compute 形态（键依次 trend_count、
    gate_count、results、pass）；results 每项含 ba/f1，二者键依次为
    regressions、worst_delta、trend、from、to、pass。返回每项
    (name, regressions_sum, worst_min) 的列表，顺序同 stats.results。
    """
    aggregated = []
    for item in stats_report["results"]:
        regressions_sum = 0
        worst_min = None
        for metric_name in ("ba", "f1"):
            block = item[metric_name]
            regressions_sum += block["regressions"]
            worst_delta = block["worst_delta"]
            if worst_min is None or worst_delta < worst_min:
                worst_min = worst_delta
        aggregated.append((item["name"], regressions_sum, worst_min))
    return aggregated


